import{_ as t,o as n,c as a,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse(`{"title":"Design Principles and Architectural Invariants","description":"Hearth's five non-negotiable judgments, core design choices, seven architectural invariants, and reference system boundaries.","frontmatter":{"title":"Design Principles and Architectural Invariants","description":"Hearth's five non-negotiable judgments, core design choices, seven architectural invariants, and reference system boundaries.","outline":[2,3]},"headers":[],"relativePath":"en/product/design-principles.md","filePath":"en/product/design-principles.md","lastUpdated":null}`),o={name:"en/product/design-principles.md"};function r(s,e,l,c,d,h){return n(),a("div",null,[...e[0]||(e[0]=[i(`<p class="eyebrow">DESIGN PRINCIPLES</p><h1 id="design-principles-and-architectural-invariants" tabindex="-1">Design Principles and Architectural Invariants <a class="header-anchor" href="#design-principles-and-architectural-invariants" aria-label="Permalink to &quot;Design Principles and Architectural Invariants&quot;">​</a></h1><p class="lead">These judgments constrain Hearth&#39;s product form, technical boundaries, and all subsequent phases. They are not suggestions, but design contracts that cannot be easily compromised.</p><h2 id="five-non-negotiable-judgments" tabindex="-1">Five Non-Negotiable Judgments <a class="header-anchor" href="#five-non-negotiable-judgments" aria-label="Permalink to &quot;Five Non-Negotiable Judgments&quot;">​</a></h2><ol><li><strong>Value lies in the Control Plane, memory, and verification—not in &quot;building another model.&quot;</strong></li><li><strong>Codex is a powerful peer Executor, not the product itself, nor the sole execution brain.</strong></li><li><strong>Token consumption is an architectural metric; wherever a model can be avoided, avoid it resolutely.</strong></li><li><strong>The frontend must be simple enough that users don&#39;t need to learn Agent architecture; complex logic stays in the backend.</strong></li><li><strong>Self-evolution can only produce candidate skills and candidate policies; it cannot bypass permissions, evaluation, and human review.</strong></li></ol><p>This version adds one delivery judgment:</p><ol start="6"><li><strong>First build a minimal product usable every day, then gradually grow it into a complete OS; the frontend exists from the first increment.</strong></li></ol><h2 id="core-design-judgments" tabindex="-1">Core Design Judgments <a class="header-anchor" href="#core-design-judgments" aria-label="Permalink to &quot;Core Design Judgments&quot;">​</a></h2><h3 id="codex-is-a-peer-executor-not-the-product-center" tabindex="-1">Codex Is a Peer Executor, Not the Product Center <a class="header-anchor" href="#codex-is-a-peer-executor-not-the-product-center" aria-label="Permalink to &quot;Codex Is a Peer Executor, Not the Product Center&quot;">​</a></h3><p>Codex excels at long-chain workspace work, code, testing, Issues/PRs, research, documentation, spreadsheets, and multi-step Shell operations; it is not suited to be long-term memory, a permission center, a credential center, a persistent event listener, or a real-time desktop operator.</p><p>The routing principle is:</p><blockquote><p><strong>Whichever Executor can complete and pass verification with the lowest Token cost, highest reliability, and least privilege—choose that one.</strong></p></blockquote><h3 id="the-boundary-between-building-and-integrating" tabindex="-1">The Boundary Between Building and Integrating <a class="header-anchor" href="#the-boundary-between-building-and-integrating" aria-label="Permalink to &quot;The Boundary Between Building and Integrating&quot;">​</a></h3><p>Hearth builds in-house:</p><ul><li>The Control Plane, Durable Harness, and Event Log protocol;</li><li>Policy, Mandate, Capability, and Approval;</li><li>Context Compiler and Token Governor;</li><li>Memory OS and Evolution OS;</li><li>Execution Gateway control logic and Credential Broker;</li><li>Task cards, approvals, Artifacts, and the mobile entry point;</li><li>Validators and the evaluation system;</li><li>The thin execution layer of the Native Runtime.</li></ul><p>Hearth integrates:</p><ul><li>Model APIs or local models;</li><li>Codex;</li><li>Playwright;</li><li>Document parsing/conversion libraries;</li><li>Official email, calendar, and cloud drive APIs/MCP;</li><li>Container/microVM/Sandbox kernels;</li><li>OpenTelemetry.</li></ul><p>Hearth does not rewrite model inference engines, container/virtualization kernels, complete third-party Agent frameworks, or document parsers.</p><h3 id="the-frontend-is-not-a-post-hoc-wrapper-layer" tabindex="-1">The Frontend Is Not a Post-Hoc Wrapper Layer <a class="header-anchor" href="#the-frontend-is-not-a-post-hoc-wrapper-layer" aria-label="Permalink to &quot;The Frontend Is Not a Post-Hoc Wrapper Layer&quot;">​</a></h3><p>When users open Hearth, they only need to know three things: what it is doing, whether it needs me, and where to click next.</p><ul><li>The home page is not an infinite chat stream, but Task cards;</li><li>Each state has only one primary action;</li><li>Approvals are not buried in multiple layers of settings;</li><li>High-risk action confirmations can be completed on mobile;</li><li>Technical jargon does not enter the main interface;</li><li>Any anomaly has an actionable recovery path;</li><li>Capabilities that exist only in the CLI, logs, database, or tests do not count toward phase completion.</li></ul><h3 id="one-logical-agent-multi-device-execution" tabindex="-1">One Logical Agent, Multi-Device Execution <a class="header-anchor" href="#one-logical-agent-multi-device-execution" aria-label="Permalink to &quot;One Logical Agent, Multi-Device Execution&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>One logical Hearth</span></span>
<span class="line"><span>  ├─ One primary Gateway / Control Plane</span></span>
<span class="line"><span>  ├─ One Event Log / single writer</span></span>
<span class="line"><span>  ├─ agentd on multiple devices</span></span>
<span class="line"><span>  ├─ Phone as the entry point for viewing, approval, takeover, and initiation</span></span>
<span class="line"><span>  └─ Each device registers its own capabilities</span></span></code></pre></div><p>Devices provide only execution capability and entry points; they do not replicate identity, the source of truth, or authorization.</p><h3 id="learn-from-openclaw-and-hermes-but-do-not-copy-them" tabindex="-1">Learn from OpenClaw and Hermes, but do not copy them <a class="header-anchor" href="#learn-from-openclaw-and-hermes-but-do-not-copy-them" aria-label="Permalink to &quot;Learn from OpenClaw and Hermes, but do not copy them&quot;">​</a></h3><p>OpenClaw is worth learning from for its Gateway, channels, device nodes, always-on residency, autonomy tiers, and attention entry points; Hermes is worth learning from for its memory budgets, memory constraints, skill crystallization, subtask lifecycle, and evolution loop.</p><p>Do not fork them, do not depend on them at runtime, and do not let reference projects become the product&#39;s foundation. Hearth absorbs patterns only and implements them through its own Event Log, Policy, Memory, and Evolution protocols.</p><h2 id="seven-architectural-invariants" tabindex="-1">Seven architectural invariants <a class="header-anchor" href="#seven-architectural-invariants" aria-label="Permalink to &quot;Seven architectural invariants&quot;">​</a></h2><ol><li>The Event Log is the single source of truth.</li><li>Each State Root has exactly one write authority.</li><li>Every external side effect must have an idempotency key, an approval or an explicit exemption, and a Receipt.</li><li>Executors must not read long-lived raw credentials directly.</li><li>Every task must have a budget, a deadline, and a cancellation path.</li><li>Memory must have provenance, sensitivity, conflict, and forgetting policies.</li><li>Any self-evolution must go through evaluation, canary, and rollback.</li></ol><p>Plus one delivery invariant:</p><ol start="8"><li><strong>Every increment must be a usable vertical slice: user outcome, interface, durable state, real execution, verification, recovery, and metrics all present at once.</strong></li></ol><h2 id="positioning-of-reference-systems" tabindex="-1">Positioning of reference systems <a class="header-anchor" href="#positioning-of-reference-systems" aria-label="Permalink to &quot;Positioning of reference systems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Reference</th><th>What to learn</th><th>What not to do</th></tr></thead><tbody><tr><td>OpenClaw</td><td>Gateway, channels, devices, attention, always-on residency</td><td>Do not fork; do not replicate its channel scale</td></tr><tr><td>Hermes</td><td>Memory budgets, skills, lifecycle, evolution</td><td>Do not do unbounded self-modification</td></tr><tr><td>DeerFlow</td><td>Harness/App layering, Run lifecycle</td><td>Do not introduce heavy framework coupling</td></tr><tr><td>Pi / Maka</td><td>session tree, steering, compaction</td><td>Do not copy the entire framework</td></tr><tr><td>OpenSandbox / OpenBot</td><td>Isolation, snapshots, takeover, receipt</td><td>Do not copy the entire product</td></tr><tr><td>OpenMuse / OpenDots</td><td>durable job, checkpoint, lease</td><td>Do not copy the task model verbatim</td></tr><tr><td>Codex</td><td>Workspace execution, code, research, documentation</td><td>Do not use it as a permission center or memory center</td></tr></tbody></table><h2 id="chapter-conclusion" tabindex="-1">Chapter conclusion <a class="header-anchor" href="#chapter-conclusion" aria-label="Permalink to &quot;Chapter conclusion&quot;">​</a></h2><p>Hearth&#39;s moat is not &quot;having a stronger model,&quot; but knowing when not to call a model, what minimal context to give an executor, which actions require whose authorization, how to prove a task is truly complete, how to recover after failure, what to remember, and what to forget.</p><p>But all of this must first appear as a genuinely usable minimal product, rather than waiting until the architecture is fully complete before users see it.</p>`,36)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
